insert into events (id, title, category, start_date, end_date, start_time, city, place, price_text, is_free, dates_tbc, date_text, description, link, sources, status, verified_at) values ('festival-sica-2026', 'Festival SICA – 20e édition', 'festival', '2026-11-09', '2026-11-15', null, 'Cotonou', 'Cotonou – soirée de gala au Palais des Congrès', 'Non communiqué', false, false, null, 'Le Festival des stars de l''intégration culturelle africaine revient dans sa ville de naissance pour ses 25 ans. Vingt-six pays sont annoncés, avec des compétitions artistiques, des rencontres professionnelles et une soirée de gala au Palais des Congrès.', null, '[{"label": "Matin Libre, 6 nov. 2026", "url": "https://matinlibre.com/2026/11/06/festival-sica-apres-cinq-editions-itinerantes-le-rendez-vous-revient-a-cotonou/"}]'::jsonb, 'publie', now()) on conflict (id) do nothing;
insert into events (id, title, category, start_date, end_date, start_time, city, place, price_text, is_free, dates_tbc, date_text, description, link, sources, status, verified_at) values ('sima-2026', 'SIMA 2026 – Salon des industries musicales d''Afrique francophone', 'conference', '2026-11-12', '2026-11-13', null, 'Cotonou', 'Cotonou', 'Non communiqué', false, false, null, 'Deux journées professionnelles de panels et de rencontres B2B sur l''intelligence artificielle, le droit d''auteur, la mobilité des artistes et le financement de la musique africaine. Artistes annoncés : A''Salfo, Tiakola, Suspect 95, Hiro et Singuila.', null, '[{"label": "Capmad", "url": "https://www.capmad.com/article/sima-2026-cotonou-accueille-la-troisieme-edition-du-salon-musical-francophone-les-12-et-13-novembre"}, {"label": "SenePlus", "url": "https://www.seneplus.com/article/cotonou-accueillera-la-3e-edition-du-sima-en-novembre-2026"}, {"label": "Afrimag", "url": "https://afrimag.net/benin-sima-2026-cotonou-industrie-musicale-tiakola-angelo-gopee/"}]'::jsonb, 'publie', now()) on conflict (id) do nothing;
insert into events (id, title, category, start_date, end_date, start_time, city, place, price_text, is_free, dates_tbc, date_text, description, link, sources, status, verified_at) values ('art-design-architecture-forum-2026', 'Art, Design & Architecture Forum – Cotonou Art Week', 'culture', '2026-11-13', '2026-11-13', null, 'Cotonou', 'Golden Tulip Cotonou', 'Non communiqué', false, false, null, 'Temps fort de la Cotonou Art Week : un forum consacré à l''art, au design et à l''architecture. La semaine propose aussi des journées portes ouvertes d''ateliers, des visites d''expositions et des rencontres avec des artistes.', null, '[{"label": "Little Africa", "url": "https://littleafrica.fr/little-africa-x-cotonou-art-week-pour-une-immersion-au-coeur-des-scenes-artistiques-et-culturelles-du-benin/"}]'::jsonb, 'publie', now()) on conflict (id) do nothing;
