insert into events (id, title, category, start_date, end_date, start_time, city, place, price_text, is_free, dates_tbc, date_text, description, link, sources, status, verified_at) values ('festival-yetin-2026', 'Festival Yêtin 2026', 'festival', '2026-12-26', '2026-12-29', null, 'Abomey-Calavi · Kétou · Torri · Cotonou', 'Yêtin Bar (Calavi), Chez Félix (Kétou), Sous les Lauriers (Torri), Pura Vida (Cotonou)', 'Pass 4 jours en prévente : 8 500 FCFA · 2 000 FCFA par site', false, false, null, 'Édition inaugurale d''un festival franco-canado-béninois sur quatre sites : e-gaming, patrimoine vodun, masterclasses afro, arts vivants et conte. Grande soirée de clôture le 29 décembre au Pura Vida, à Cotonou (pass VIP 18 000 FCFA).', 'https://art-hum.org/lefestivales.php', '[{"label": "Site du festival", "url": "https://art-hum.org/lefestivales.php"}]'::jsonb, 'publie', now()) on conflict (id) do nothing;
