insert into events (id, title, category, start_date, end_date, start_time, city, place, price_text, is_free, dates_tbc, date_text, description, link, sources, status, verified_at) values ('cotonou-comedy-festival-2026', 'Cotonou Comedy Festival 2026', 'humour', '2026-12-01', '2026-12-31', null, 'Cotonou', 'Cotonou', 'Non communiqué', false, true, 'Décembre 2026 – dates à confirmer', 'Deuxième édition du festival international d''humour lancé en 2025 par le gouvernement béninois avec le groupe Montreux Comedy. La première édition avait réuni galas, masterclasses et un village du rire gratuit. Les dates exactes de 2026 ne sont pas encore publiées.', 'https://cotonoucomedy.com/', '[{"label": "Gouvernement du Bénin – bilan 2025", "url": "https://www.gouv.bj/doc/905/download"}]'::jsonb, 'publie', now()) on conflict (id) do nothing;
